const ordersUrl = "https://www.target.com/orders";
const historyPath = "/post_orders/v1/orders/history";

/**
 * Read only the order-history response generated by Target's Orders page.
 * Never log or return order numbers, addresses, payment details, or raw URLs.
 * An unexpected redirect (including /cart) leaves this check inconclusive.
 */
async function readTargetOrderHistory(context) {
  const page = await context.newPage();
  let history = null;
  const onResponse = async (response) => {
    try {
      const url = new URL(response.url());
      if (
        url.hostname === "api.target.com" &&
        url.pathname === historyPath &&
        response.status() === 200
      ) {
        history = await response.json();
      }
    } catch (error) {
      // An unreadable response is not order confirmation.
    }
  };
  page.on("response", onResponse);
  try {
    await page.goto(ordersUrl, {
      waitUntil: "domcontentloaded",
      timeout: 20000,
    });
    for (let tick = 0; tick < 100 && !history; tick += 1) {
      if (new URL(page.url()).pathname !== "/orders") {
        return null;
      }
      await page.waitForTimeout(100);
    }
    return new URL(page.url()).pathname === "/orders" ? history : null;
  } catch (error) {
    return null;
  } finally {
    page.off("response", onResponse);
    await page.close().catch(() => {});
  }
}

function classifyOrderHistory(history, { productId, submittedAt } = {}) {
  const expectedTcin = String(productId || "").match(/^A-(\d{7,})$/)?.[1];
  const submittedTime = Date.parse(submittedAt);
  if (
    !expectedTcin ||
    !Number.isFinite(submittedTime) ||
    !Array.isArray(history?.orders)
  ) {
    return "unknown";
  }
  // Allow a small clock skew, but exclude an earlier order for the same item.
  const earliestOrderTime = submittedTime - 5000;
  let matches = 0;
  for (const order of history.orders) {
    const orderTime = Date.parse(order?.order_date);
    if (
      !Number.isFinite(orderTime) ||
      orderTime < earliestOrderTime ||
      order.order_type !== "Sales"
    ) {
      continue;
    }
    const lines = (order.packages || [])
      .flatMap((pkg) => pkg.order_lines || []);
    if (!lines.some((line) => String(line?.item?.tcin) === expectedTcin)) {
      continue;
    }
    if (
      lines.length !== 1 ||
      String(lines[0].item.tcin) !== expectedTcin ||
      Number(lines[0].quantity) !== 1
    ) {
      return "ambiguous";
    }
    matches += 1;
  }
  return matches === 1
    ? "confirmed"
    : matches > 1
      ? "ambiguous"
      : "absent";
}

async function confirmTargetOrder({
  productId,
  submittedAt,
  readHistory,
  attempts = 12,
  intervalMs = 10000,
  wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
} = {}) {
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    let history = null;
    try {
      history = await readHistory();
    } catch (error) {
      // A failed read does not establish that an order is absent.
    }
    const outcome = classifyOrderHistory(history, {
      productId,
      submittedAt,
    });
    if (outcome === "confirmed" || outcome === "ambiguous") {
      return outcome;
    }
    if (attempt + 1 < attempts) {
      await wait(intervalMs);
    }
  }
  return "unknown";
}

module.exports = {
  classifyOrderHistory,
  confirmTargetOrder,
  readTargetOrderHistory,
};
